import { Book } from "@/lib/types";

export const _2corinthians: Book = {
  id: "2corinthians",
  name: "2. Korinther",
  shortName: "2.Kor",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Paulus, Apostel* Christi Jesu durch Gottes Willen*, und Timotheus*, der Bruder, der Gemeinde* Gottes, die in Korinth* ist, samt allen Heiligen, die in ganz Achaja sind:", heading: "Verfasser, Empfänger und Gruß", footnotes: ["d. h. Gesandter, o. Bote", "℘ 1Kor 1,1", "℘ Apg 16,1; Phil 1,1; Kol 1,1; 1Thes 1,1; 2Thes 1,1; 1Tim 1,2; 2Tim 1,2", "o. Versammlung", "℘ Apg 18,1"] },
      { number: 2, text: "Gnade euch und Friede von Gott, unserem Vater, und dem Herrn Jesus Christus*!", footnotes: ["℘ Röm 1,7"] },
      { number: 3, text: "Gepriesen sei der Gott* und Vater unseres Herrn Jesus Christus*, der Vater der Erbarmungen und Gott allen Trostes*,", heading: "Dank für Gottes Rettung aus Todesgefahr", footnotes: ["℘ Ps 68,36", "℘ Eph 1,3; 1Petr 1,3", "℘ Kap. 7,6"] },
      { number: 4, text: "der uns tröstet* in all unserer Bedrängnis*, damit wir die trösten können, die in allerlei Bedrängnis sind, durch den Trost, mit dem wir selbst von Gott getröstet werden.", footnotes: ["o. aller Ermunterung, 4 der uns ermuntert; so auch nachher", "℘ Ps 94,19"] },
      { number: 5, text: "Denn wie die Leiden des Christus überreich auf uns kommen*, so ist auch durch den Christus unser Trost überreich.", footnotes: ["℘ 1Kor 4,11"] },
      { number: 6, text: "Sei es aber, dass wir bedrängt werden, so ist es zu eurem Trost und Heil*; sei es, dass wir getröstet werden, so ist es zu eurem Trost, der wirksam wird im geduldigen Ertragen* derselben Leiden, die auch wir leiden*.", footnotes: ["o. Rettung", "o. Ausharren in", "℘ Kap. 4,15; Phil 1,29"] },
      { number: 7, text: "Und unsere Hoffnung für euch steht fest, da wir wissen, dass, wie ihr der Leiden teilhaftig seid, so auch des Trostes." },
      { number: 8, text: "Denn wir wollen euch nicht in Unkenntnis lassen, Brüder*, über unsere Bedrängnis, die uns in Asien* widerfahren ist*, dass wir übermäßig beschwert wurden, über Vermögen, so dass wir sogar am Leben verzweifelten.", footnotes: ["℘ 1Kor 10,1", "d. i. die röm. Provinz Asien; vgl. auch Anm. zu Apg 16,6", "℘ 1Kor 16,9"] },
      { number: 9, text: "Wir selbst aber hatten in uns selbst* schon das Urteil des Todes erhalten, damit wir nicht auf uns selbst vertrauten, sondern auf Gott, der die Toten auferweckt*.", footnotes: ["℘ Kap. 4,10; 6,9; 11,23", "℘ Röm 4,17"] },
      { number: 10, text: "Und der hat uns aus so großer Todesgefahr* gerettet und wird uns retten; auf ihn hoffen wir, dass er uns auch ferner retten werde*;", footnotes: ["w. aus so großem Tod", "℘ Ps 34,20; 2Tim 3,11; 4,18"] },
      { number: 11, text: "wobei auch ihr durch das Gebet für uns mitwirkt*, damit von vielen Personen für das uns verliehene Gnadengeschenk* gedankt werde, durch viele für uns.", footnotes: ["℘ Röm 15,30; Phil 1,19; Kol 4,3", "griech. charisma; d. h. einfach »Gabe« oder »Geschenk«; im NT ist meist eine Gabe Gottes bzw. des Geistes gemeint"] },
      { number: 12, text: "Denn unser Rühmen ist dies: das Zeugnis unseres Gewissens*, dass wir in Einfalt* und Lauterkeit Gottes*, nicht in fleischlicher Weisheit*, sondern in der Gnade Gottes gewandelt sind in der Welt, besonders* aber bei euch*.", heading: "Verteidigung gegen unberechtigte Vorwürfe", footnotes: ["℘ Apg 24,16", "Viele alte Handschr. haben: Heiligkeit", "℘ Kap. 2,17", "℘ 1Kor 2,13", "w. überströmender", "℘ 1Thes 2,10"] },
      { number: 13, text: "Denn wir schreiben euch nichts anderes, als was ihr lest oder auch erkennt; ich hoffe aber, dass ihr bis ans Ende erkennen werdet," },
      { number: 14, text: "wie ihr auch uns zum Teil erkannt habt, dass wir euer Ruhm sind*, so wie auch ihr der unsrige seid am Tag unseres Herrn Jesus*.", footnotes: ["℘ Kap. 5,12", "℘ Kap. 7,4; 1Kor 1,8; Phil 2,16; 1Thes 2,19"] },
      { number: 15, text: "Und in diesem Vertrauen wollte ich vorher zu euch kommen*, damit ihr eine zweite Gnade hättet,", footnotes: ["℘ 1Kor 4,19"] },
      { number: 16, text: "und über euch nach Mazedonien reisen und wieder von Mazedonien zu euch kommen und von euch nach Judäa geleitet werden*.", footnotes: ["℘ 1Kor 16,5.6"] },
      { number: 17, text: "Habe ich nun, indem ich mir dieses vornahm, etwa leichtfertig gehandelt? Oder was ich mir vornehme, nehme ich mir das nach dem Fleisch vor, damit bei mir das Ja-ja und das Nein-nein gleichzeitig wären*?", footnotes: ["℘ Mt 5,37"] },
      { number: 18, text: "Gott aber ist treu und bürgt dafür, dass unser Wort an euch nicht Ja und Nein zugleich ist." },
      { number: 19, text: "Denn der Sohn Gottes, Christus Jesus, der unter euch durch uns gepredigt worden ist*, durch mich und Silvanus* und Timotheus*, war nicht Ja und Nein, sondern in ihm ist ein Ja geschehen.", footnotes: ["℘ Apg 9,20", "d. i. Silas", "℘ Apg 18,5"] },
      { number: 20, text: "Denn so viele Verheißungen Gottes es gibt, in ihm ist das Ja, deshalb auch durch ihn das Amen*, Gott zur Ehre durch uns.", footnotes: ["Beteuerungs- und Bestätigungsformel für die Wahrhaftigkeit des Gesagten; vgl. auch Anm. zu Röm 1,25\n℘ Offb 3,14"] },
      { number: 21, text: "Der uns aber mit euch festigt in Christus* und uns gesalbt hat, ist Gott*,", footnotes: ["℘ Röm 16,25", "℘ 1Jo 2,20"] },
      { number: 22, text: "der uns auch versiegelt* und die Anzahlung des Geistes in unsere Herzen gegeben hat*.", footnotes: ["℘ Kap. 5,5; Eph 1,13; 1Thes 4,8", "℘ Röm 5,5; 8,16.23"] },
      { number: 23, text: "Ich aber rufe Gott zum Zeugen an gegen meine Seele*, dass ich, um euch zu schonen, noch nicht nach Korinth gekommen bin*.", footnotes: ["℘ Kap. 11,31", "℘ Kap. 12,20; 13,2"] },
      { number: 24, text: "Nicht dass wir über euren Glauben herrschen*, sondern wir sind Mitarbeiter an eurer Freude*; denn ihr steht durch den Glauben*.", footnotes: ["℘ 1Petr 5,3", "℘ Phil 1,25", "℘ 1Kor 16,13"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Ich habe aber dies für mich beschlossen, nicht wieder in Traurigkeit zu euch zu kommen*.", footnotes: ["℘ Kap. 12,21"] },
      { number: 2, text: "Denn wenn ich euch traurig mache, wer ist dann noch da, der mich fröhlich mache außer dem, der durch mich traurig gemacht wird*?", footnotes: ["℘ Kap. 7,12.13"] },
      { number: 3, text: "Und ebendieses habe ich euch geschrieben*, damit ich nicht, wenn ich komme, von denen Traurigkeit habe, von denen ich Freude haben sollte, weil ich euch allen vertraue*, dass meine Freude euer aller Freude ist*.", footnotes: ["℘ Kap. 7,8.9", "℘ Gal 5,10", "℘ Kap. 7,16"] },
      { number: 4, text: "Denn aus viel Bedrängnis und Herzensangst schrieb ich euch mit vielen Tränen*, nicht damit ihr traurig gemacht würdet, sondern damit ihr die Liebe erkennen möchtet, die ich besonders zu euch habe.", footnotes: ["℘ Apg 20,19.31"] },
      { number: 5, text: "Wenn euch aber jemand traurig gemacht hat, so hat er nicht mich traurig gemacht, sondern zum Teil — damit ich nicht zu viel sage — euch alle.", heading: "Das bußfertige Gemeindeglied soll wieder aufgenommen werden" },
      { number: 6, text: "Dem Betreffenden genügt diese Strafe von den meisten der Gemeinde," },
      { number: 7, text: "so dass ihr im Gegenteil vielmehr vergeben* und ermuntern* solltet, damit der Betreffende nicht etwa durch allzu große Traurigkeit verschlungen werde.", footnotes: ["o. Gnade erweisen", "o. trösten"] },
      { number: 8, text: "Darum ermahne ich euch, zu beschließen, ihm gegenüber Liebe zu üben." },
      { number: 9, text: "Denn dazu habe ich auch geschrieben, dass ich eure Bewährung kennenlernte, ob ihr in allem gehorsam seid*.", footnotes: ["℘ Kap. 7,15"] },
      { number: 10, text: "Wem ihr aber etwas vergebt, dem vergebe auch ich; denn auch ich habe, was ich vergeben habe — wenn ich etwas zu vergeben hatte —, um euretwillen vergeben vor dem Angesicht Christi*,", footnotes: ["℘ Kol 3,13"] },
      { number: 11, text: "damit wir nicht vom Satan übervorteilt werden*; denn seine Gedanken sind uns nicht unbekannt*.", footnotes: ["℘ Eph 4,27; 6,11", "℘ Lk 22,31; 1Petr 5,8"] },
      { number: 12, text: "Als ich aber zur Verkündigung des Evangeliums* Christi nach Troas kam und mir eine Tür geöffnet wurde im Herrn*,", heading: "Verkündigung des Evangeliums in Mazedonien", footnotes: ["w. Als ich aber für das Evangelium", "℘ 1Kor 16,9"] },
      { number: 13, text: "hatte ich keine Ruhe in meinem Geist, weil ich Titus, meinen Bruder, nicht fand, sondern ich nahm Abschied von ihnen und zog fort nach Mazedonien*.", footnotes: ["℘ Kap. 7,5.6; Apg 20,1.2"] },
      { number: 14, text: "Gott aber sei Dank, der uns allezeit im Triumphzug umherführt in Christus und den Geruch seiner Erkenntnis an jedem Ort durch uns offenbart!" },
      { number: 15, text: "Denn wir sind ein Wohlgeruch Christi für Gott unter* denen, die gerettet werden, und unter* denen, die verloren gehen;", footnotes: ["o. in", "o. in"] },
      { number: 16, text: "den einen ein Geruch vom Tod zum Tode, den anderen aber ein Geruch vom Leben zum Leben*. Und wer ist dazu tüchtig*?", footnotes: ["Anspielung auf die römischen Triumphzüge, bei denen wohlriechende Kräuter verbrannt wurden. Da bei dieser Gelegenheit Gefangene sowohl getötet als auch verschont wurden, war der »Wohlgeruch« den einen ein Geruch »zum Tode«, den anderen »zum Leben«.", "℘ Kap. 3,5.6"] },
      { number: 17, text: "Denn wir treiben keinen Handel mit dem Wort Gottes* wie die meisten*, sondern wie aus Lauterkeit und wie aus Gott reden wir vor Gott in Christus*.", footnotes: ["℘ Kap. 4,2; 1Thes 2,3", "w. wie die vielen\n℘ Kap. 11,13", "℘ Kap. 1,12; 12,19; 2Tim 2,15; 1Petr 4,11"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Fangen wir wieder an, uns selbst zu empfehlen*? Oder brauchen wir etwa, wie gewisse Leute Empfehlungsbriefe, an euch oder Empfehlungsbriefe von euch?", heading: "Die Korinther als Empfehlungsbrief des Apostels", footnotes: ["℘ Kap. 5,12; 10,12"] },
      { number: 2, text: "Unser Brief seid ihr, eingeschrieben in unsere Herzen, erkannt und gelesen von allen Menschen;" },
      { number: 3, text: "von euch ist offenbar geworden, dass ihr ein Brief Christi seid, ausgefertigt von uns im Dienst*, geschrieben nicht mit Tinte, sondern mit dem Geist des lebendigen Gottes*, nicht auf steinerne Tafeln*, sondern auf Tafeln, die fleischerne Herzen sind*.", footnotes: ["w. von uns bedient\n℘ 1Kor 9,2", "℘ Kap. 6,7; 1Kor 2,4", "℘ 2Mo 24,12", "℘ Hes 11,19; 36,26"] },
      { number: 4, text: "Solches Vertrauen aber haben wir durch Christus zu Gott:", heading: "Vorzug des neuen Bundes vor dem alten" },
      { number: 5, text: "Nicht dass wir von uns aus tüchtig wären, etwas zu erdenken* als aus uns selbst, sondern unsere Tüchtigkeit ist von Gott*,", footnotes: ["o. denken, erwägen", "℘ Kap. 2,16; Joh 15,5; 1Kor 15,10"] },
      { number: 6, text: "der uns auch tüchtig gemacht hat* zu Dienern des neuen Bundes*, nicht des Buchstabens*, sondern des Geistes. Denn der Buchstabe tötet*, der Geist aber macht lebendig*.", footnotes: ["℘ 1Tim 1,12", "℘ 1Kor 11,25", "℘ Röm 2,29", "℘ Röm 4,15", "℘ Joh 6,63"] },
      { number: 7, text: "Wenn aber schon der Dienst des Todes, mit Buchstaben in Steine eingegraben*, in Herrlichkeit geschah, so dass die Söhne Israels nicht fest in das Angesicht Moses schauen konnten wegen der Herrlichkeit seines Angesichts*, die doch verging,", footnotes: ["℘ 5Mo 10,3.4", "℘ 2Mo 34,30"] },
      { number: 8, text: "wie wird nicht vielmehr der Dienst des Geistes in Herrlichkeit bestehen*?", footnotes: ["w. sein"] },
      { number: 9, text: "Denn wenn der Dienst der Verdammnis* Herrlichkeit ist, so ist der Dienst der Gerechtigkeit* noch viel reicher an Herrlichkeit.", footnotes: ["℘ 5Mo 27,26; Gal 3,10", "℘ Röm 1,17; 3,21; Hebr 8,6"] },
      { number: 10, text: "Denn in dieser Hinsicht ist sogar das Verherrlichte nicht verherrlicht wegen der überragenden Herrlichkeit." },
      { number: 11, text: "Denn wenn das Vergehende* in Herrlichkeit war, wie viel mehr besteht das Bleibende in Herrlichkeit!", footnotes: ["℘ Hebr 7,18"] },
      { number: 12, text: "Da wir nun eine solche Hoffnung haben, so gehen wir mit großer Freimütigkeit vor" },
      { number: 13, text: "und tun nicht wie Mose, der eine Decke über sein Angesicht legte, damit die Söhne Israels nicht auf das Ende des Vergehenden blicken sollten*.", footnotes: ["℘ 2Mo 34,33.35"] },
      { number: 14, text: "Aber ihr Sinn ist* verstockt worden*, denn bis auf den heutigen Tag bleibt dieselbe Decke auf der Verlesung des Alten Testaments und wird nicht aufgedeckt, weil sie nur in Christus beseitigt wird.", footnotes: ["w. ihre Gedanken sind", "℘ Jes 6,10; Röm 11,7.25"] },
      { number: 15, text: "Aber bis heute, sooft Mose gelesen wird, liegt eine Decke auf ihrem Herzen." },
      { number: 16, text: "Dann aber, wenn es sich zum Herrn wendet, wird die Decke weggenommen*.", footnotes: ["℘ Röm 11,23; 2Mo 34,34"] },
      { number: 17, text: "Der Herr aber ist der Geist*; wo aber der Geist des Herrn ist, ist Freiheit*.", footnotes: ["℘ 1Kor 15,45", "℘ Joh 8,32.36"] },
      { number: 18, text: "Wir alle aber schauen mit aufgedecktem Angesicht* die Herrlichkeit des Herrn an* und werden so verwandelt in dasselbe Bild* von Herrlichkeit zu Herrlichkeit, wie es vom Herrn, dem Geist, geschieht.", footnotes: ["℘ 2Mo 34,34", "o. spiegeln . . . wider", "℘ Röm 8,29"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Darum, da wir diesen Dienst haben*, weil* wir ja Erbarmen gefunden haben*, ermatten wir nicht*;", heading: "Die Lauterkeit des Apostels bei der Verkündigung des Evangeliums", footnotes: ["℘ Kap. 3,6", "w. wie", "℘ 1Kor 7,25", "o. werden wir nicht mutlos"] },
      { number: 2, text: "sondern wir haben den geheimen Dingen, deren man sich schämen muss*, entsagt und wandeln nicht in Arglist, noch verfälschen* wir das Wort Gottes*, sondern durch die Offenbarung der Wahrheit empfehlen wir uns jedem Gewissen der Menschen vor Gott*.", footnotes: ["w. den geheimen Dingen der Scham (o. der Schande)", "o. gebrauchen wir betrügerisch", "℘ Kap. 2,17", "℘ Kap. 13,8"] },
      { number: 3, text: "Wenn aber unser Evangelium doch verdeckt ist, so ist es nur bei denen verdeckt, die verloren gehen*,", footnotes: ["℘ 1Kor 1,18; 2Thes 2,10"] },
      { number: 4, text: "den Ungläubigen, bei denen der Gott dieser Welt* den Sinn* verblendet hat, damit sie den Lichtglanz des Evangeliums von der Herrlichkeit des Christus*, der Gottes Bild ist*, nicht sehen.", footnotes: ["o. dieses Zeitalters (griech. Äon)", "w. die Gedanken", "℘ 1Tim 1,11", "℘ Kol 1,15; Hebr 1,3"] },
      { number: 5, text: "Denn wir predigen nicht uns selbst, sondern Christus Jesus als Herrn*, uns aber als eure Sklaven um Jesu willen*.", footnotes: ["℘ Röm 10,9", "℘ Mt 20,27; 1Kor 3,5"] },
      { number: 6, text: "Denn Gott, der gesagt hat: »Aus Finsternis wird Licht leuchten!«*, er ist es, der in unseren Herzen aufgeleuchtet ist* zum Lichtglanz der Erkenntnis der Herrlichkeit Gottes im Angesicht Jesu Christi*.", footnotes: ["℘ 1Mo 1,3", "℘ Eph 5,8", "mit mehreren alten Handschr.: im Angesicht Christi\n℘ Joh 12,45"] },
      { number: 7, text: "Wir haben aber diesen Schatz in irdenen Gefäßen, damit das Übermaß* der Kraft von Gott* sei und nicht aus uns*.", heading: "Gottes Kraft hält Paulus in seinen Leiden aufrecht", footnotes: ["o. das Außerordentliche; o. das Außergewöhnliche", "w. Gottes", "℘ 1Kor 2,5"] },
      { number: 8, text: "In allem sind wir bedrängt*, aber nicht erdrückt; keinen Ausweg sehend, aber nicht ohne Ausweg*;", footnotes: ["℘ Kap. 1,8; 7,5", "o. in Zweifel, aber nicht in Verzweiflung\n℘ Ps 129,2"] },
      { number: 9, text: "verfolgt*, aber nicht verlassen; niedergeworfen, aber nicht vernichtet;", footnotes: ["℘ 2Tim 3,12"] },
      { number: 10, text: "allezeit das Sterben Jesu am* Leib umhertragend*, damit auch das Leben Jesu an* unserem Leibe offenbar werde.", footnotes: ["o. in dem", "℘ Kap. 1,9; 1Kor 15,31; Gal 6,17; Phil 3,10", "o. in"] },
      { number: 11, text: "Denn ständig werden wir, die Lebenden, dem Tod überliefert um Jesu willen*, damit auch das Leben Jesu an unserem sterblichen Fleisch offenbar werde*.", footnotes: ["℘ Lk 9,23; Röm 8,36", "℘ Kap. 6,9"] },
      { number: 12, text: "Folglich wirkt der Tod in uns, das Leben aber in euch." },
      { number: 13, text: "Da wir aber denselben Geist des Glaubens haben — nach dem, was geschrieben steht: »Ich habe geglaubt, darum habe ich geredet«* —, so glauben auch wir, darum reden wir auch;", footnotes: ["℘ Ps 116,10"] },
      { number: 14, text: "denn wir wissen, dass der, welcher den Herrn Jesus auferweckt hat, auch uns mit Jesus auferwecken und mit euch vor sich stellen wird*;", footnotes: ["℘ 1Kor 6,14"] },
      { number: 15, text: "denn alles geschieht um euretwillen*, damit die Gnade zunehme und durch eine immer größere Zahl die Danksagung zur Ehre* Gottes überreich mache*.", footnotes: ["℘ Kap. 1,6; 2Tim 2,10", "o. Herrlichkeit", "℘ Kap. 9,12; Kol 2,7"] },
      { number: 16, text: "Deshalb ermatten wir nicht*, sondern wenn auch unser äußerer Mensch aufgerieben wird, so wird doch der innere* Tag für Tag erneuert*.", footnotes: ["o. werden wir nicht mutlos", "℘ Röm 7,22", "℘ Ps 84,8; Kol 3,10"] },
      { number: 17, text: "Denn das schnell vorübergehende* Leichte unserer Bedrängnis bewirkt uns ein über die Maßen überreiches, ewiges Gewicht von Herrlichkeit*,", footnotes: ["℘ 1Petr 1,6", "℘ Röm 8,18"] },
      { number: 18, text: "da wir nicht das Sichtbare anschauen, sondern das Unsichtbare*; denn das Sichtbare ist zeitlich, das Unsichtbare aber ewig.", footnotes: ["℘ Hebr 11,1"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Denn wir wissen, dass, wenn unser irdisches Zelthaus* zerstört wird, wir einen Bau von* Gott haben, ein nicht mit Händen gemachtes, ewiges Haus in den Himmeln*.", heading: "Sehnsucht des Apostels nach der himmlischen Behausung", footnotes: ["℘ 2Petr 1,13.14", "o. aus", "℘ Hebr 11,10"] },
      { number: 2, text: "Denn in diesem freilich seufzen wir und sehnen uns danach, mit unserer Behausung aus dem Himmel überkleidet zu werden*,", footnotes: ["℘ Röm 8,23"] },
      { number: 3, text: "insofern wir ja bekleidet, nicht nackt befunden werden." },
      { number: 4, text: "Denn wir freilich, die in dem Zelt sind, seufzen beschwert, weil wir nicht entkleidet, sondern überkleidet werden möchten, damit das Sterbliche verschlungen werde vom Leben*.", footnotes: ["℘ 1Kor 15,51.53"] },
      { number: 5, text: "Der uns aber eben hierzu bereitet hat, ist Gott*, der uns die Anzahlung des Geistes gegeben hat*.", footnotes: ["℘ Joh 1,13", "℘ Kap. 1,21.22"] },
      { number: 6, text: "So sind wir nun allezeit guten Mutes und wissen, dass wir, während ›einheimisch‹ im Leib, wir vom Herrn ›ausheimisch‹ sind" },
      { number: 7, text: "— denn wir wandeln durch Glauben, nicht durch Schauen* —;", footnotes: ["℘ Joh 20,29; Röm 8,24"] },
      { number: 8, text: "wir sind aber guten Mutes und möchten lieber ›ausheimisch‹ vom Leib und ›einheimisch‹ beim Herrn sein*.", footnotes: ["℘ Phil 1,23"] },
      { number: 9, text: "Deshalb setzen wir auch unsere Ehre darein, ob ›einheimisch‹ oder ›ausheimisch‹, ihm wohlgefällig zu sein*.", footnotes: ["℘ 2Tim 2,4"] },
      { number: 10, text: "Denn wir müssen alle vor dem Richterstuhl Christi offenbar werden*, damit jeder empfange, was er durch den Leib vollbracht, dementsprechend, was er getan hat*, es sei Gutes oder Böses*.", footnotes: ["℘ Röm 14,10", "℘ 1Kor 4,5; Eph 6,8", "℘ Mt 25,19; Röm 2,6"] },
      { number: 11, text: "Da wir nun den Schrecken des Herrn* kennen, so überreden wir Menschen, Gott aber sind wir offenbar geworden; ich hoffe aber, auch in euren Gewissen offenbar zu sein.", heading: "Eifer des Apostels in der Verkündigung des Evangeliums", footnotes: ["o. die Furcht des Herrn (d. h. wir wissen, wie sehr der Herr zu fürchten ist)"] },
      { number: 12, text: "Wir empfehlen uns nicht wieder selbst bei euch*, sondern geben euch Anlass zum Ruhm unsertwegen*, damit ihr ihn habt bei denen, die sich nach dem Ansehen rühmen und nicht nach dem Herzen.", footnotes: ["℘ Kap. 3,1", "℘ Kap. 1,14"] },
      { number: 13, text: "Denn sei es, dass wir außer uns waren, so waren wir es für Gott; sei es, dass wir vernünftig sind, so sind wir es für euch." },
      { number: 14, text: "Denn die Liebe Christi drängt uns, da wir zu diesem Urteil gekommen sind*, dass einer für alle gestorben ist und somit alle gestorben sind*.", footnotes: ["℘ 1Kor 2,15", "℘ Röm 6,5"] },
      { number: 15, text: "Und für alle ist er gestorben, damit die, welche leben, nicht mehr sich selbst leben, sondern dem, der für sie gestorben* und auferweckt worden ist*.", footnotes: ["℘ 1Kor 15,3; 1Thes 5,10", "℘ Röm 14,7.8; Phil 2,21"] },
      { number: 16, text: "Daher kennen wir von nun an niemand nach dem Fleisch; wenn wir Christus auch nach dem Fleisch gekannt haben, so kennen wir ihn doch jetzt nicht mehr so." },
      { number: 17, text: "Daher, wenn jemand in Christus ist, so ist er eine neue Schöpfung*; das Alte ist vergangen, siehe, Neues ist geworden*.", footnotes: ["℘ Gal 6,15; Eph 2,10", "℘ Röm 6,4; Offb 21,5"] },
      { number: 18, text: "Alles aber von Gott, der uns mit sich selbst versöhnt hat durch Christus* und uns den Dienst der Versöhnung gegeben hat,", heading: "Der Dienst der Versöhnung", footnotes: ["℘ Röm 5,10; Eph 2,16"] },
      { number: 19, text: "nämlich dass Gott in Christus war* und die Welt mit sich selbst versöhnte, ihnen ihre Übertretungen nicht zurechnete* und in uns das Wort von der Versöhnung gelegt hat.", footnotes: ["℘ Joh 10,38", "w. dass Gott in Christus war, die Welt mit sich selbst versöhnend, ihnen ihre Übertretungen nicht zurechnend"] },
      { number: 20, text: "So sind wir nun Gesandte* an Christi Statt, indem Gott gleichsam durch uns ermahnt; wir bitten für Christus: Lasst euch versöhnen mit Gott!", footnotes: ["o. wirken wir nun als Gesandte\n℘ Eph 6,20"] },
      { number: 21, text: "Den, der Sünde nicht kannte*, hat er für uns zur Sünde gemacht*, damit wir Gottes Gerechtigkeit würden in ihm*.", footnotes: ["℘ Joh 8,46", "℘ Röm 8,3", "℘ Röm 3,21; 5,19; 1Kor 1,30; Phil 3,9"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "Als Mitarbeiter* aber ermahnen* wir auch, dass ihr die Gnade Gottes nicht vergeblich empfangt*.", heading: "Bewährung des Apostels im Dienst", footnotes: ["℘ 1Kor 3,9", "o. bitten", "℘ 1Kor 15,2; Hebr 12,15"] },
      { number: 2, text: "Denn er spricht: »Zur willkommenen* Zeit habe ich dich erhört, und am Tage des Heils habe ich dir geholfen.«* Siehe, jetzt* ist die hochwillkommene Zeit, siehe, jetzt* ist der Tag des Heils.", footnotes: ["o. wohlgefälligen", "℘ Jes 49,8", "℘ Hebr 3,7", "℘ Kap. 7,16"] },
      { number: 3, text: "Und wir geben in keiner Sache irgendeinen Anstoß*, damit der Dienst nicht verlästert werde,", footnotes: ["℘ 1Kor 10,32"] },
      { number: 4, text: "sondern in allem empfehlen wir uns als Gottes Diener*, in vielem Ausharren*, in Bedrängnissen*, in Nöten, in Ängsten*,", footnotes: ["℘ 1Kor 4,1", "o. viel Standhaftigkeit, Geduld\n℘ Kap. 12,12", "℘ 2Tim 3,10.11", "℘ Kap. 12,10"] },
      { number: 5, text: "in Schlägen*, in Gefängnissen*, in Tumulten*, in Mühen*, in Wachen*, in Fasten*;", footnotes: ["℘ Kap. 11,23-25", "℘ Apg 16,23", "℘ Apg 21,30", "℘ 1Thes 2,9", "℘ Apg 20,31", "℘ Kap. 11,27"] },
      { number: 6, text: "in Reinheit*, in Erkenntnis*, in Langmut*, in Güte, im Heiligen Geist, in ungeheuchelter Liebe*;", footnotes: ["℘ 1Tim 4,12", "℘ Kap. 11,6", "℘ 2Tim 2,24.25", "℘ Röm 12,9"] },
      { number: 7, text: "im Reden der Wahrheit, in der Kraft Gottes*; durch die Waffen der Gerechtigkeit zur Rechten und zur Linken*;", footnotes: ["℘ Röm 15,19; 1Kor 2,4", "℘ Kap. 10,4"] },
      { number: 8, text: "durch Ehre und Unehre, durch böse und gute Nachrede, als Verführer und Wahrhaftige;" },
      { number: 9, text: "als Unbekannte und Wohlbekannte*; als Sterbende*, und siehe, wir leben*; als Gezüchtigte und doch nicht getötet*;", footnotes: ["o. Wohlerkannte", "℘ 1Kor 4,9", "℘ Kap. 1,8-10; 4,10.11", "℘ Ps 118,18"] },
      { number: 10, text: "als Traurige, aber allezeit uns freuend*; als Arme, aber viele reich machend*; als nichts habend und doch alles besitzend.", footnotes: ["℘ Kap. 7,4", "℘ Eph 3,8"] },
      { number: 11, text: "Unser Mund hat sich euch gegenüber geöffnet, ihr Korinther; unser Herz ist weit geworden.", heading: "Warnung vor Gemeinschaft mit Ungläubigen — Werben um die Liebe der Korinther" },
      { number: 12, text: "Ihr seid nicht beengt in uns, sondern ihr seid beengt in euren eigenen Herzen*.", footnotes: ["o. in eurem Innern; w. in euren Eingeweiden\n℘ Kap. 12,15"] },
      { number: 13, text: "Als Gegenleistung* aber — ich rede wie zu Kindern — werdet auch ihr weit!", footnotes: ["w. Zur gleichen (o. entsprechenden) Vergeltung"] },
      { number: 14, text: "Geht nicht unter fremdartigem Joch* mit Ungläubigen*! Denn welche Verbindung haben Gerechtigkeit und Gesetzlosigkeit? Oder welche Gemeinschaft Licht mit Finsternis*?", footnotes: ["o. Seid (o. Werdet) nicht verschiedenartig zusammengejocht", "℘ 5Mo 7,2.3; 22,10", "℘ 1Mo 1,4; Eph 5,7-11"] },
      { number: 15, text: "Und welche Übereinstimmung Christus mit Belial*? Oder welches Teil ein Gläubiger mit einem Ungläubigen?", footnotes: ["w. Beliar. — Das hebr. Belial bedeutet »Ruchloser«, womit der Satan bezeichnet wird.\n℘ 5Mo 13,14"] },
      { number: 16, text: "Und welchen Zusammenhang der Tempel Gottes mit Götzenbildern*? Denn wir sind der Tempel des lebendigen Gottes*; wie Gott gesagt hat: »Ich will unter ihnen wohnen und wandeln, und ich werde ihr Gott sein, und sie werden mein Volk sein.«*", footnotes: ["℘ 1Kor 10,21", "℘ 1Kor 3,16.17", "℘ 3Mo 26,11.12; Hes 37,27; Hebr 8,10"] },
      { number: 17, text: "Darum geht aus ihrer Mitte hinaus und sondert euch ab*!, spricht der Herr*. Und rührt Unreines nicht an*! Und ich werde euch annehmen*", footnotes: ["℘ Jer 51,45; Offb 18,4", "℘ 4Mo 16,20.21", "℘ Jes 52,11", "℘ Hes 20,40.41"] },
      { number: 18, text: "und werde euch Vater sein*, und ihr werdet mir Söhne und Töchter sein, spricht der Herr, der Allmächtige*.", footnotes: ["℘ Jer 31,9", "℘ Offb 21,7"] },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Da wir nun diese Verheißungen haben, Geliebte, so wollen wir uns reinigen* von jeder Befleckung des Fleisches und des Geistes* und die Heiligkeit vollenden in der Furcht Gottes*.", footnotes: ["℘ 1Jo 3,3", "℘ Hebr 10,22", "℘ Hebr 12,14"] },
      { number: 2, text: "Gebt uns Raum in euren Herzen! Wir haben niemand Unrecht getan, wir haben niemand zugrunde gerichtet, wir haben niemand übervorteilt*.", footnotes: ["℘ Kap. 12,17.18; Apg 20,33"] },
      { number: 3, text: "Nicht um zu verurteilen, rede ich; denn ich habe vorhin gesagt, dass ihr in unseren Herzen seid*, um mitzusterben und mitzuleben.", footnotes: ["℘ Kap. 6,11.12"] },
      { number: 4, text: "Groß ist meine Freimütigkeit euch gegenüber, groß mein Rühmen über euch*; ich bin mit Trost erfüllt*, ich bin überreich an Freude bei all unserer Bedrängnis*.", footnotes: ["℘ Kap. 1,14; 2Thes 1,4", "℘ Phim 7", "℘ Kap. 6,10; 1Thes 3,7.9"] },
      { number: 5, text: "Denn auch als wir nach Mazedonien kamen*, hatte unser Fleisch keine Ruhe, sondern in allem waren wir bedrängt; von außen Kämpfe*, von innen Ängste*.", heading: "Paulus ist durch den Bericht des Titus über die Korinther getröstet", footnotes: ["℘ Kap. 2,13", "℘ 1Thes 2,2", "℘ Kap. 4,8; 11,28"] },
      { number: 6, text: "Aber der die Niedrigen tröstet, Gott*, tröstete uns durch die Ankunft des Titus*;", footnotes: ["℘ Kap. 1,3", "℘ Kap. 2,13"] },
      { number: 7, text: "doch nicht nur durch seine Ankunft, sondern auch durch den Trost, womit er bei euch* getröstet worden ist, denn er berichtete uns eure Sehnsucht, euer Wehklagen, euren Eifer für mich, so dass ich mich noch mehr freute.", footnotes: ["o. euretwegen"] },
      { number: 8, text: "Denn wenn ich euch auch durch den Brief* betrübt habe, so reut es mich nicht. *Wenn es mich auch gereut hat, so sehe ich, dass jener Brief, wenn er euch auch kurze Zeit betrübt hat, doch Segen gewirkt hat; und", footnotes: ["℘ Kap. 2,3.4", "mit anderen Handschr.: Wenn es mich auch gereut hat — denn ich sehe, dass jener Brief euch, wenn auch nur kurze Zeit, betrübt hat —, 9 freue ich mich doch jetzt"] },
      { number: 9, text: "jetzt freue ich mich*, nicht dass ihr betrübt worden, sondern dass ihr zur Buße betrübt worden seid; denn ihr seid nach Gottes Sinn betrübt worden, damit ihr in keiner Weise von uns Schaden erlittet.", footnotes: ["mit anderen Handschr.: Wenn es mich auch gereut hat — denn ich sehe, dass jener Brief euch, wenn auch nur kurze Zeit, betrübt hat —, 9 freue ich mich doch jetzt"] },
      { number: 10, text: "Denn die Betrübnis nach Gottes Sinn bewirkt eine nie zu bereuende Buße zum Heil*; die Betrübnis der Welt aber bewirkt den Tod.", footnotes: ["o. zur Rettung"] },
      { number: 11, text: "Denn siehe, ebendies, dass ihr nach Gottes Sinn betrübt worden seid*, wie viel Bemühen hat es bei euch bewirkt! Sogar Verteidigung, sogar Unwillen, sogar Furcht, sogar Sehnsucht, sogar Eifer, sogar Bestrafung! In allem habt ihr bewiesen, dass ihr in der Sache rein seid.", footnotes: ["℘ 1Kor 5,2"] },
      { number: 12, text: "Wenn ich euch also auch geschrieben habe, so geschah es nicht wegen des Beleidigers*, auch nicht wegen des Beleidigten*, sondern damit euer Bemühen um uns* bei euch offenbar werde vor Gott.", footnotes: ["w. dessen, der Unrecht getan hat", "w. dessen, der Unrecht erlitten hat", "Andere Handschr. lesen: euer Bemühen um euch, o. unser Bemühen um euch"] },
      { number: 13, text: "Deswegen sind wir getröstet worden*. Außer unserem Trost aber freuten wir uns noch viel mehr über die Freude des Titus, denn sein Geist ist durch euch alle erquickt worden*.", footnotes: ["℘ Kap. 2,2", "℘ Phim 7.20"] },
      { number: 14, text: "Denn wenn ich ihm etwas Rühmendes über euch gesagt habe, so bin ich nicht zuschanden geworden; sondern wie wir alles in Wahrheit zu euch geredet haben, so ist auch unser Rühmen vor Titus Wahrheit geworden*;", footnotes: ["℘ Kap. 8,24"] },
      { number: 15, text: "und sein Herz* ist euch besonders zugetan, wenn er an euer aller Gehorsam denkt*, wie ihr ihn mit Furcht und Zittern empfangen habt*.", footnotes: ["o. Inneres; w. seine Eingeweide", "℘ Kap. 2,9", "℘ Phil 2,12.13"] },
      { number: 16, text: "Ich freue mich, dass ich in allem Zutrauen zu euch habe*.", footnotes: ["o. guter Zuversicht im Blick auf euch bin\n℘ Kap. 2,3; 2Thes 3,4; Phim 21"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Wir tun euch aber, Brüder, die Gnade Gottes kund, die in den Gemeinden* Mazedoniens gegeben worden ist,", heading: "Aufforderung zur Sammlung für die Gemeinde in Jerusalem", footnotes: ["o. Versammlungen"] },
      { number: 2, text: "dass bei großer Bewährung in Bedrängnis sich der Überschwang ihrer Freude und ihre tiefe Armut als überreich erwiesen haben in dem* Reichtum ihrer Aufrichtigkeit* im Geben*.", footnotes: ["w. in den . . . hinein", "o. Schlichtheit; w. Einfalt", "℘ Röm 12,8; 15,26"] },
      { number: 3, text: "Denn nach Vermögen, ich bezeuge es, und über Vermögen waren sie aus eigenem Antrieb willig" },
      { number: 4, text: "und baten uns mit vielem Zureden um die Gnade und die Beteiligung am Dienst für die Heiligen*.", footnotes: ["℘ Kap. 9,1; Apg 11,29"] },
      { number: 5, text: "Und nicht nur so, wie wir hofften, sondern sie gaben sich selbst zuerst dem Herrn und dann uns durch Gottes Willen," },
      { number: 6, text: "so dass wir Titus zugeredet haben, er möge bei euch ebenfalls dieses Gnadenwerk auch so vollenden, wie er es früher angefangen hatte*.", footnotes: ["℘ V. 16.17; Kap. 12,18"] },
      { number: 7, text: "Aber so wie ihr in allem überreich seid*: in Glauben und Wort und Erkenntnis und allem Eifer und der Liebe, die von uns in euch* geweckt ist, so möget ihr auch in diesem Gnadenwerk* überströmend sein*.", footnotes: ["℘ 1Kor 1,5", "Andere Handschr. lesen: von euch in uns", "w. mit (o. in) dieser Gnade", "℘ 1Kor 16,2"] },
      { number: 8, text: "Nicht befehlsweise spreche ich*, sondern um durch den Eifer anderer auch die Echtheit eurer Liebe zu prüfen*.", footnotes: ["℘ 1Kor 7,6", "℘ 1Jo 3,17.18"] },
      { number: 9, text: "Denn ihr kennt die Gnade unseres Herrn Jesus Christus, dass er, da er reich war, um euretwillen arm wurde*, damit ihr durch seine Armut reich würdet.", footnotes: ["℘ Mt 8,20; Phil 2,6-8"] },
      { number: 10, text: "Und ich gebe hierin eine Meinung ab; denn das ist euch nützlich, die ihr nicht allein das Tun, sondern auch das Wollen vorher angefangen habt — seit vorigem Jahr*.", footnotes: ["℘ Kap. 9,2-4"] },
      { number: 11, text: "Nun aber vollendet auch das Tun, damit, wie die Bereitwilligkeit des Wollens, so auch das Vollbringen da ist, nach dem, was ihr habt*.", footnotes: ["℘ 1Kor 16,1"] },
      { number: 12, text: "Denn wenn die Bereitwilligkeit da ist, so ist sie willkommen nach dem, was sie hat, und nicht nach dem, was sie nicht hat*.", footnotes: ["℘ Mk 12,43"] },
      { number: 13, text: "Denn das sage ich nicht, damit andere Erleichterung haben, ihr aber Bedrängnis, sondern nach Maßgabe der Gleichheit:" },
      { number: 14, text: "In der jetzigen Zeit diene euer Überfluss dem Mangel jener*, damit auch der Überfluss jener für euren Mangel diene, damit Gleichheit entstehe;", footnotes: ["℘ Kap. 9,12; Apg 2,45"] },
      { number: 15, text: "wie geschrieben steht: »Wer viel sammelte, hatte keinen Überfluss, und wer wenig sammelte, hatte keinen Mangel.«*", footnotes: ["℘ 2Mo 16,18"] },
      { number: 16, text: "Gott aber sei Dank, der denselben Eifer für euch in das Herz des Titus gegeben hat;", heading: "Empfehlung des Titus und anderer Brüder als Überbringer der Liebesgaben" },
      { number: 17, text: "denn er nahm zwar das Zureden an, doch weil er noch eifriger war, ist er aus eigenem Antrieb zu euch gegangen*.", footnotes: ["w. hinausgegangen\n℘ V. 6"] },
      { number: 18, text: "Wir haben aber den Bruder mit ihm gesandt*, dessen Lob wegen der Verkündigung des Evangeliums durch alle Gemeinden* verbreitet ist.", footnotes: ["℘ Kap. 9,3; 12,18", "o. Versammlungen; so auch V. 19.23.24"] },
      { number: 19, text: "Aber nicht allein das, sondern er ist auch von den Gemeinden zu unserem Reisegefährten in diesem Gnadenwerk* gewählt worden, das von uns besorgt wird* zur Herrlichkeit des Herrn selbst und als Beweis unserer Bereitwilligkeit*;", footnotes: ["w. mit (o. in) dieser Gnade", "℘ 1Kor 16,3", "w. und zu unserer Geneigtheit (o. Bereitwilligkeit)"] },
      { number: 20, text: "denn wir suchen das zu verhüten, dass uns jemand übel nachredet dieser reichen Gabe wegen, die von uns besorgt wird;" },
      { number: 21, text: "denn wir sind auf das Rechte* bedacht, nicht allein vor dem Herrn, sondern auch vor den Menschen*.", footnotes: ["o. das Gute, das Schöne, das Lobenswerte", "℘ Apg 24,16; Röm 12,17; 1Kor 10,32; 1Thes 4,12"] },
      { number: 22, text: "Wir haben aber unseren Bruder mit ihnen gesandt*, den wir oft in vielem als eifrig erprobt haben, der nun aber noch viel eifriger ist durch das große Vertrauen, das er zu euch hat.", footnotes: ["℘ Kap. 9,3; 12,18"] },
      { number: 23, text: "Sei es, was Titus betrifft*, er ist mein Gefährte und in Bezug auf euch mein Mitarbeiter*; seien es unsere Brüder, sie sind Gesandte* der Gemeinden*, Christi Herrlichkeit.", footnotes: ["℘ Tit 1,4", "℘ Gal 2,1", "griech. apostoloi", "℘ Phil 2,25"] },
      { number: 24, text: "So erbringt nun ihnen gegenüber angesichts der Gemeinden den Beweis eurer Liebe und der Berechtigung unseres Rühmens über euch*!", footnotes: ["℘ Kap. 7,14"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "Denn was den Dienst für die Heiligen betrifft, so ist es überflüssig für mich, euch zu schreiben*.", footnotes: ["℘ Kap. 8,4.20"] },
      { number: 2, text: "Denn ich kenne eure Bereitwilligkeit, die ich zu euren Gunsten den Mazedoniern gegenüber rühme, dass Achaja seit vorigem Jahr bereit ist*; und euer Eifer hat die Mehrzahl angereizt.", footnotes: ["℘ Kap. 8,10"] },
      { number: 3, text: "Ich habe aber die Brüder gesandt*, damit unser Rühmen über euch in dieser Beziehung nicht zunichte würde, damit ihr, wie ich gesagt habe, bereit seid und", footnotes: ["℘ Kap. 8,18.22"] },
      { number: 4, text: "damit nicht etwa, wenn die Mazedonier mit mir kommen und euch unvorbereitet finden, wir — um nicht zu sagen: ihr — in dieser Lage* zuschanden würden.", footnotes: ["o. Erwartung"] },
      { number: 5, text: "Ich hielt es daher für nötig, die Brüder zu bitten, dass sie zu euch vorauszögen und diese eure zuvor angekündigte Segensgabe vorher zubereiteten, damit diese so bereit sei wie eine Gabe des Segens und nicht des Geizes*.", footnotes: ["w. so bereit sei wie Segen und nicht wie Geiz (o. Habsucht)"] },
      { number: 6, text: "Dies aber sage ich: Wer sparsam sät, wird auch sparsam ernten, und wer segensreich* sät, wird auch segensreich* ernten*.", heading: "Vom Segen freudigen Gebens", footnotes: ["o. freigebig, reichlich", "o. freigebig, reichlich", "℘ Spr 11,24; Lk 6,38; Gal 6,7.9"] },
      { number: 7, text: "Jeder gebe, wie er sich in seinem Herzen vorgenommen hat: nicht mit Verdruss* oder aus Zwang*, denn einen fröhlichen Geber liebt Gott*.", footnotes: ["w. aus Betrübnis", "℘ 5Mo 15,10; 1Chr 29,9; Phim 14", "℘ Röm 12,8"] },
      { number: 8, text: "Gott aber vermag euch jede Gnade* überreichlich zu geben*, damit ihr in allem allezeit alle Genüge habt* und überreich seid zu jedem guten Werk;", footnotes: ["o. Wohltat", "℘ 1Petr 5,10", "℘ Phil 4,19"] },
      { number: 9, text: "wie geschrieben steht: »Er hat ausgestreut, er hat den Armen gegeben; seine Gerechtigkeit bleibt in Ewigkeit*.«*", footnotes: ["griech. Äon", "℘ Ps 112,9"] },
      { number: 10, text: "Der aber Samen darreicht dem Sämann* und Brot zur Speise, wird eure Saat darreichen und mehren und die Früchte eurer Gerechtigkeit wachsen lassen*,", footnotes: ["℘ Jes 55,10", "℘ Hos 10,12; Phil 1,11"] },
      { number: 11, text: "und ihr werdet in allem reich gemacht zu aller Aufrichtigkeit* im Geben, die durch uns Danksagung Gott gegenüber bewirkt.", footnotes: ["o. Schlichtheit; w. Einfalt"] },
      { number: 12, text: "Denn die Besorgung dieses Dienstes* füllt nicht nur den Mangel der Heiligen aus*, sondern ist auch überreich durch viele Danksagungen zu Gott*;", footnotes: ["Das hier benutzte griech. Wort meint, im Gegensatz zum Wort »Dienst« (diakonia) in V. 13, stets »Gottesdienst« (liturgia).", "℘ Kap. 8,14; Röm 15,26", "℘ Kap. 4,15"] },
      { number: 13, text: "denn infolge der Bewährung dieses Dienstes verherrlichen sie Gott wegen des Gehorsams eures Bekenntnisses zum Evangelium Christi und wegen der Lauterkeit der Gemeinschaft mit ihnen und mit allen*;", footnotes: ["w. zu ihnen und zu allen"] },
      { number: 14, text: "und im Gebet für euch sehnen sie sich nach euch wegen der überragenden Gnade Gottes an euch." },
      { number: 15, text: "Gott sei Dank für seine unaussprechliche Gabe*!", footnotes: ["℘ Joh 4,10"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Ich selbst aber, Paulus, ermahne euch durch die Sanftmut und Milde Christi*, der ich ins Gesicht zwar demütig unter euch, abwesend aber mutig gegen euch bin.", heading: "Paulus verteidigt sich gegen persönliche Angriffe", footnotes: ["℘ Mt 11,29"] },
      { number: 2, text: "Ich bitte aber darum, dass ich anwesend nicht mutig sein muss, mit der Zuversicht, mit der ich gedenke, gewissen Leuten gegenüber kühn aufzutreten*, die von uns denken*, wir wandelten nach dem Fleisch.", footnotes: ["℘ V. 11; Kap. 13,2.10; 1Kor 4,21", "o. die uns beurteilen"] },
      { number: 3, text: "Denn obwohl wir im Fleisch wandeln, kämpfen wir nicht nach dem Fleisch*;", footnotes: ["℘ Röm 8,12"] },
      { number: 4, text: "denn die Waffen unseres Kampfes sind nicht fleischlich, sondern mächtig für* Gott zur Zerstörung von Festungen; so zerstören wir überspitzte Gedankengebäude*", footnotes: ["o. in, o. durch", "o. Berechnungen, Beurteilungen"] },
      { number: 5, text: "und jede Höhe, die sich gegen die Erkenntnis Gottes erhebt, und nehmen jeden Gedanken* gefangen unter* den Gehorsam Christi*", footnotes: ["o. jede Wahrnehmung", "o. in", "℘ Röm 1,5"] },
      { number: 6, text: "und sind bereit, allen Ungehorsam zu strafen, wenn euer Gehorsam erfüllt sein wird." },
      { number: 7, text: "Seht doch auf das, was vor Augen ist! Wenn jemand sich zutraut, dass er Christus angehört*, so denke er andererseits dies bei sich selbst, dass, wie er Christus angehört, so auch wir.", footnotes: ["℘ 1Kor 1,12"] },
      { number: 8, text: "Denn wenn ich mich auch etwas mehr über unsere Vollmacht rühme, die uns der Herr zu eurer Erbauung* und nicht zu eurer Zerstörung gegeben hat*, so werde ich nicht zuschanden werden,", footnotes: ["o. zu eurem Aufbau", "℘ Kap. 13,10; Eph 4,12"] },
      { number: 9, text: "damit ich nicht den Anschein erwecke, als wolle ich euch nur durch die Briefe schrecken." },
      { number: 10, text: "Denn die Briefe, sagt man, sind gewichtig und stark, aber die leibliche Gegenwart ist schwach* und die Rede zu verachten*.", footnotes: ["℘ Kap. 11,21; 1Kor 2,3", "℘ Kap. 11,6"] },
      { number: 11, text: "Derjenige bedenke dies, dass, wie wir abwesend im Wort durch Briefe sind, so auch anwesend mit der Tat sein werden*.", footnotes: ["℘ V. 2"] },
      { number: 12, text: "Denn wir wagen nicht, uns gewissen Leuten von denen, die sich selbst empfehlen*, beizuzählen oder gleichzustellen; aber da sie sich an sich selbst messen und sich mit sich selbst vergleichen, sind sie unverständig.", footnotes: ["℘ Kap. 3,1"] },
      { number: 13, text: "Wir aber wollen uns nicht ins Maßlose rühmen*, sondern nach dem Maße des Wirkungskreises*, den uns Gott als Maß zugeteilt hat, nämlich auch bis zu euch zu gelangen.", footnotes: ["℘ Röm 12,3", "o. der Richtschnur; so auch V. 15.16"] },
      { number: 14, text: "Denn es ist nicht so, als ob wir nicht zu euch gekommen wären und uns nun zu weit ausstreckten; denn wir sind mit dem Evangelium Christi auch bis zu euch gekommen;" },
      { number: 15, text: "dabei rühmen wir uns nicht ins Maßlose mit fremden Arbeitsleistungen*, haben vielmehr die Hoffnung, wenn euer Glaube wächst, unter euch entsprechend unserem Wirkungskreis groß gemacht zu werden bis zum Übermaß", footnotes: ["℘ Röm 15,20"] },
      { number: 16, text: "und dann das Evangelium weiter über euch hinaus zu verkündigen, nicht in fremdem Wirkungskreis uns dessen zu rühmen, was schon fertig ist*.", footnotes: ["℘ Röm 15,20"] },
      { number: 17, text: "»Wer sich aber rühmt, rühme sich des* Herrn!«*", footnotes: ["w. im", "℘ Jer 9,23; 1Kor 1,31"] },
      { number: 18, text: "Denn nicht, wer sich selbst empfiehlt, der ist bewährt, sondern der, den der Herr empfiehlt." },
    ]},
    { number: 11, verses: [
      { number: 1, text: "Möget ihr doch ein wenig Torheit von mir ertragen! Doch ihr ertragt mich ja auch.", heading: "Lauterkeit des Apostels, Unlauterkeit der falschen Apostel" },
      { number: 2, text: "Denn ich eifere um euch mit Gottes Eifer; denn ich habe euch einem Mann verlobt*, um euch als eine keusche Jungfrau vor den Christus hinzustellen*.", footnotes: ["℘ Hos 2,21.22", "℘ Offb 14,4"] },
      { number: 3, text: "Ich fürchte aber, dass, wie die Schlange Eva durch ihre List verführte*, so vielleicht euer Sinn* von der Einfalt *und Lauterkeit* Christus gegenüber abgewandt und verdorben wird.", footnotes: ["℘ 1Mo 3,1-6; 1Tim 2,14; Offb 12,9", "w. eure Gedanken, o. eure Wahrnehmungen", "in einigen Handschr. nicht enthalten", "in einigen Handschr. nicht enthalten"] },
      { number: 4, text: "Denn wenn der, welcher kommt, einen anderen Jesus predigt, den wir nicht gepredigt haben, oder ihr einen anderen* Geist empfangt, den ihr nicht empfangen habt, oder ein anderes* Evangelium, das ihr nicht angenommen habt*, so ertragt ihr das recht gut.", footnotes: ["o. verschiedenen; o. andersartigen; ein anderes Wort als vorher", "o. verschiedenen; o. andersartigen; ein anderes Wort als vorher", "℘ Gal 1,6"] },
      { number: 5, text: "Denn ich meine, dass ich den »übergroßen« Aposteln in nichts nachgestanden habe*.", footnotes: ["℘ Kap. 12,11"] },
      { number: 6, text: "Wenn ich aber auch ein Unkundiger in der Rede bin*, so doch nicht in der Erkenntnis*; sondern in jeder Weise und vor allen haben wir es euch gegenüber offenbar gemacht*.", footnotes: ["℘ Kap. 10,10; 1Kor 2,1", "℘ Kap. 6,6; Eph 3,4", "℘ Kap. 12,12"] },
      { number: 7, text: "Oder habe ich eine Sünde begangen, als ich mich selbst erniedrigte, damit ihr erhöht würdet, indem ich euch das Evangelium Gottes umsonst verkündigt habe*?", footnotes: ["℘ Apg 18,3; 1Kor 9,6.12.18"] },
      { number: 8, text: "Andere Gemeinden* habe ich beraubt, indem ich Lohn nahm zum Dienst an euch.", footnotes: ["o. Versammlungen"] },
      { number: 9, text: "Und als ich bei euch war und Mangel litt, fiel ich niemand zur Last — denn meinem Mangel halfen die Brüder ab, die aus Mazedonien kamen* —, und ich hielt mich in allem so, dass ich euch nicht zur Last fiel, und werde mich so halten*.", footnotes: ["℘ Phil 4,15", "℘ Kap. 12,13.14; 1Thes 2,9"] },
      { number: 10, text: "So gewiss die Wahrheit Christi in mir ist, wird dieses Rühmen für mich in den Gegenden von Achaja nicht verstummen*!", footnotes: ["℘ 1Kor 9,15"] },
      { number: 11, text: "Warum? Weil ich euch nicht liebe*? Gott weiß es.", footnotes: ["℘ Kap. 12,15; 1Kor 16,24"] },
      { number: 12, text: "Was ich aber tue, werde ich auch tun, damit ich denen die Gelegenheit abschneide, die eine Gelegenheit dazu suchen, dass sie in dem, worin sie sich rühmen, als solche wie wir befunden werden." },
      { number: 13, text: "Denn solche sind falsche Apostel*, betrügerische Arbeiter*, die die Gestalt von Aposteln Christi annehmen.", footnotes: ["℘ Kap. 2,17; Offb 2,2", "℘ Röm 16,18; Phil 3,2"] },
      { number: 14, text: "Und kein Wunder, denn der Satan selbst nimmt die Gestalt eines Engels des Lichts an;" },
      { number: 15, text: "es ist daher nichts Großes, wenn auch seine Diener die Gestalt von Dienern der Gerechtigkeit annehmen; und ihr Ende wird ihren Werken entsprechen*.", footnotes: ["℘ Gal 5,10; Phil 3,19"] },
      { number: 16, text: "Wiederum sage ich: Niemand halte mich für töricht; wenn aber doch, so nehmt mich doch an als einen Törichten, damit auch ich mich ein wenig rühmen kann*.", heading: "Bewährung des Apostels in Leiden und Schwachheiten", footnotes: ["℘ Kap. 12,6"] },
      { number: 17, text: "Was ich jetzt rede, rede ich nicht nach dem Herrn, sondern wie in Torheit, auf dieser Grundlage des Rühmens." },
      { number: 18, text: "Weil viele sich nach dem Fleisch rühmen, so will auch ich mich rühmen*.", footnotes: ["℘ Phil 3,4"] },
      { number: 19, text: "Ihr als Kluge ertragt die Toren ja gern*.", footnotes: ["℘ 1Kor 4,10"] },
      { number: 20, text: "Denn ihr ertragt es, wenn jemand euch knechtet, wenn jemand euch aufzehrt, wenn jemand euch einfängt, wenn jemand sich überhebt, wenn jemand euch ins Gesicht schlägt." },
      { number: 21, text: "Zur Schande sage ich, dass wir damit verglichen schwach gewesen sind*. Was aber jemand wagt — ich rede in Torheit —, das wage auch ich.", footnotes: ["℘ Kap. 10,10"] },
      { number: 22, text: "Sie sind Hebräer? Ich auch. Sie sind Israeliten? Ich auch*. Sie sind Abrahams Nachkommen*? Ich auch*.", footnotes: ["℘ Röm 11,1", "w. Same", "℘ Röm 15,20"] },
      { number: 23, text: "Sie sind Diener Christi? — Ich rede unsinnig — ich über die Maßen*. In Mühen umso mehr, in Gefängnissen umso mehr*, in Schlägen übermäßig*, in Todesgefahren oft*.", footnotes: ["℘ Apg 9,16", "℘ Kap. 6,4.5", "℘ 1Kor 4,11", "℘ Kap. 1,8-10; 1Kor 15,30-31"] },
      { number: 24, text: "Von den Juden habe ich fünfmal vierzig Schläge weniger einen bekommen*.", footnotes: ["s. Anm. zu Mt 10,17; so auch V. 25. Die Strafe betrug 39 Schläge, damit die durch das Gesetz vorgeschriebene Zahl von 40 Schlägen nicht aus Versehen überschritten wurde.\n℘ 5Mo 25,3; Mt 10,17"] },
      { number: 25, text: "Dreimal bin ich mit Ruten geschlagen*, einmal gesteinigt worden*; dreimal habe ich Schiffbruch erlitten; einen Tag und eine Nacht habe ich in Seenot* zugebracht;", footnotes: ["℘ Apg 16,22.23", "℘ Apg 14,19", "w. in der Tiefe (d. h. des Meeres)"] },
      { number: 26, text: "oft auf Reisen, in Gefahren von Flüssen, in Gefahren von Räubern, in Gefahren von meinem Volk*, in Gefahren von den Nationen*, in Gefahren in der Stadt, in Gefahren in der Wüste, in Gefahren auf dem Meer*, in Gefahren unter falschen Brüdern*;", footnotes: ["w. Geschlecht\n℘ Apg 9,23; 1Thes 2,15", "℘ Apg 19,28", "℘ Apg 27,20", "℘ Gal 2,4"] },
      { number: 27, text: "in Mühe und Beschwerde*, in Wachen oft*, in Hunger und Durst, in Fasten oft, in Kälte* und Blöße*;", footnotes: ["℘ Apg 18,3", "℘ Kap. 6,5; Apg 20,31", "℘ Apg 28,2", "℘ 1Kor 4,12"] },
      { number: 28, text: "außer dem Übrigen noch das, was täglich auf mich eindringt: die Sorge um alle Gemeinden*.", footnotes: ["o. Versammlungen\n℘ Kap. 7,5; Apg 15,36; 20,18-21"] },
      { number: 29, text: "Wer ist schwach, und ich bin nicht schwach? Wer nimmt Anstoß*, und ich brenne nicht?", footnotes: ["o. Wer wird zur Sünde verleitet"] },
      { number: 30, text: "Wenn gerühmt werden muss, so will ich mich der Zeichen meiner Schwachheit rühmen*.", footnotes: ["℘ Kap. 12,5-10; 1Kor 2,3"] },
      { number: 31, text: "Der Gott und Vater des Herrn Jesus, der gepriesen ist in Ewigkeit*, weiß, dass ich nicht lüge*.", footnotes: ["griech. Äonen\n℘ Röm 9,5", "℘ Kap. 1,23; Röm 9,1"] },
      { number: 32, text: "In Damaskus bewachte der Statthalter des Königs Aretas* die Stadt der Damaszener, um mich gefangen zu nehmen,", footnotes: ["Schwiegervater des Herodes Antipas (s. Anm. zu Mt 14,1) und König eines arabischen Reiches im Osten Palästinas"] },
      { number: 33, text: "und durch ein Fenster wurde ich in einem Korb durch die Mauer hinabgelassen und entrann seinen Händen*.", footnotes: ["℘ Apg 9,24.25"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Gerühmt muss werden; zwar nützt es nichts, aber ich will auf Erscheinungen und Offenbarungen des Herrn kommen.", heading: "Ruhm der Offenbarungen und der eigenen Schwachheit" },
      { number: 2, text: "Ich weiß von einem Menschen in Christus, dass er vor vierzehn Jahren — ob im Leib, weiß ich nicht, oder außer dem Leib, weiß ich nicht; Gott weiß es —, dass dieser bis in den dritten Himmel entrückt wurde." },
      { number: 3, text: "Und ich weiß von dem betreffenden Menschen — ob im Leib oder außer* dem Leib, weiß ich nicht; Gott weiß es —,", footnotes: ["o. getrennt von; ein anderes Wort als V. 2"] },
      { number: 4, text: "dass er in das Paradies* entrückt wurde und unaussprechliche Worte* hörte, die auszusprechen einem Menschen nicht zusteht.", footnotes: ["℘ Lk 23,43", "o. Reden, Mitteilungen"] },
      { number: 5, text: "Über diesen will ich mich rühmen; über mich selbst aber will ich mich nicht rühmen, nur der Schwachheiten*.", footnotes: ["℘ Kap. 11,30"] },
      { number: 6, text: "Denn wenn ich mich rühmen will, werde ich doch nicht töricht sein, denn ich werde die Wahrheit sagen. Ich enthalte mich aber dessen, damit nicht jemand höher von mir denke, als was er an mir sieht oder was er von mir hört*,", footnotes: ["℘ Kap. 11,16"] },
      { number: 7, text: "auch wegen des Außerordentlichen der Offenbarungen. Darum, damit ich mich nicht überhebe*, wurde mir ein Dorn für das Fleisch gegeben, ein Engel* Satans, dass er mich mit Fäusten schlage, damit ich mich nicht überhebe.", footnotes: ["mit anderen alten Handschr.: von mir hört. 7 Und damit ich mich wegen der Außerordentlichkeit der Offenbarungen nicht überhebe", "o. Bote"] },
      { number: 8, text: "Um dessentwillen habe ich dreimal den Herrn angerufen, dass er von mir ablassen möge*.", footnotes: ["℘ Mt 26,44"] },
      { number: 9, text: "Und er hat zu mir gesagt: Meine Gnade genügt dir, denn meine Kraft kommt in Schwachheit zur Vollendung*. Sehr gerne will ich mich nun vielmehr meiner Schwachheiten rühmen, damit die Kraft Christi bei mir* wohne*.", footnotes: ["℘ Ps 138,3; Jes 40,29; Gal 4,13", "o. auf mir", "o. zelte"] },
      { number: 10, text: "Deshalb habe ich Wohlgefallen an Schwachheiten, an Misshandlungen, an Nöten, an Verfolgungen, an Ängsten um Christi willen*; denn wenn ich schwach bin, dann bin ich stark*.", footnotes: ["℘ Kap. 6,4; Apg 5,41", "℘ Phil 4,13"] },
      { number: 11, text: "Ich bin ein Tor geworden; ihr habt mich dazu gezwungen. Denn ich hätte von euch empfohlen werden sollen, denn ich habe in nichts den »übergroßen« Aposteln nachgestanden*, wenn ich auch nichts bin.", heading: "Des Apostels Werben um die Liebe der Korinther", footnotes: ["℘ Kap. 11,5"] },
      { number: 12, text: "Die Zeichen des Apostels sind ja unter euch vollbracht worden in allem Ausharren*, in Zeichen und Wundern und Machttaten*.", footnotes: ["℘ Kap. 6,4", "℘ Kap. 11,6; Röm 15,19; 1Kor 9,2"] },
      { number: 13, text: "Was ist es denn, worin ihr gegenüber den übrigen Gemeinden* zu kurz gekommen seid, außer dass ich selbst euch nicht zur Last gefallen bin*? Verzeiht mir dieses Unrecht*.", footnotes: ["o. Versammlungen", "℘ Kap. 11,9; 1Kor 9,12", "℘ Kap. 11,7"] },
      { number: 14, text: "Siehe, dieses dritte Mal stehe ich bereit, zu euch zu kommen*, und werde euch nicht zur Last fallen, denn ich suche nicht das Eure*, sondern euch. Denn die Kinder sollen nicht für die Eltern Schätze sammeln, sondern die Eltern für die Kinder.", footnotes: ["℘ Kap. 13,1", "℘ Apg 20,33.34"] },
      { number: 15, text: "Ich will aber sehr gern alles aufwenden und mich aufopfern für eure Seelen*. Wenn ich euch also noch mehr liebe, werde ich dann weniger wiedergeliebt*?", footnotes: ["℘ Phil 2,17; 2Tim 2,10", "℘ Kap. 6,12; 11,11"] },
      { number: 16, text: "Doch es sei: Ich habe euch nicht belastet; weil ich aber schlau bin, habe ich euch mit List gefangen." },
      { number: 17, text: "Habe ich euch etwa durch einen von denen übervorteilt, die ich zu euch gesandt habe*?", footnotes: ["℘ Kap. 7,2"] },
      { number: 18, text: "Ich habe Titus gebeten und den Bruder mit ihm gesandt*. Hat etwa Titus euch übervorteilt? Sind wir nicht in demselben Geist gewandelt? Nicht in denselben Fußspuren?", footnotes: ["℘ Kap. 8,6.18"] },
      { number: 19, text: "Seit langem seid ihr der Meinung, dass wir uns vor euch verteidigen*. Wir reden vor Gott in Christus*, alles aber, Geliebte, zu eurer Erbauung*.", heading: "Mahnung zur Buße — Hoffnung auf Zurechtbringung der Korinther", footnotes: ["℘ 1Kor 9,3", "℘ Kap. 2,17", "o. zu eurem Aufbau\n℘ Röm 14,19"] },
      { number: 20, text: "Denn ich fürchte, dass ich euch bei meinem Kommen vielleicht nicht als solche finde, wie ich will, und dass ich von euch als solcher befunden werde, wie ihr nicht wollt*: dass vielleicht Streit, Eifersucht*, Zorn*, Selbstsüchteleien, Verleumdungen, üble Nachreden, Aufgeblasenheit, Unordnungen* da sind*;", footnotes: ["℘ Kap. 1,23", "o. Neid\n℘ Jak 3,16", "Im Griech. steht »Zorn« in der Mehrzahl.", "o. Unruhen", "℘ 1Kor 1,11; 4,6"] },
      { number: 21, text: "dass, wenn ich wiederkomme, mein Gott mich vor euch demütigt und ich über viele trauern muss*, die vorher gesündigt und nicht Buße getan haben über die Unreinheit und Unzucht und Ausschweifung, die sie getrieben haben*.", footnotes: ["℘ Kap. 2,1", "℘ Kap. 13,2; 1Kor 5,1"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Zum dritten Mal komme ich jetzt zu euch*: Durch zweier oder dreier Zeugen Mund wird jede Sache* festgestellt werden*.", footnotes: ["℘ Kap. 12,14", "o. jeder Ausspruch", "℘ 5Mo 19,18; Mt 18,16"] },
      { number: 2, text: "Ich habe es im Voraus gesagt und sage es im Voraus, wie das zweite Mal anwesend, so auch jetzt abwesend, denen, die vorher gesündigt haben*, und allen Übrigen, dass, wenn ich wiederkomme, ich nicht schonen werde*.", footnotes: ["℘ Kap. 12,20.21", "℘ Kap. 1,23; 10,2.6.11"] },
      { number: 3, text: "Denn ihr fordert ja einen Beweis dafür, dass Christus in mir redet, der gegen euch nicht schwach ist, sondern mächtig unter euch;" },
      { number: 4, text: "denn er wurde zwar aus Schwachheit gekreuzigt*, aber er lebt aus Gottes Kraft*; denn auch wir sind schwach in ihm, aber wir werden mit ihm leben aus Gottes Kraft euch gegenüber.", footnotes: ["℘ Phil 2,7.8", "℘ Eph 1,19.20"] },
      { number: 5, text: "Prüft euch, ob ihr im Glauben seid*, untersucht euch*! Oder erkennt ihr euch selbst nicht, dass Jesus Christus in euch ist*? Es sei denn, dass ihr etwa unbewährt seid.", footnotes: ["℘ Hebr 3,12", "℘ 1Kor 11,28; Gal 6,4", "℘ Joh 17,26"] },
      { number: 6, text: "Ich hoffe jedoch, dass ihr erkennen werdet, dass wir nicht unbewährt sind." },
      { number: 7, text: "Wir beten aber zu Gott, dass ihr nichts Böses tun möget; nicht damit wir bewährt erscheinen, sondern damit ihr das Gute tut, wir aber wie Unbewährte sind." },
      { number: 8, text: "Denn wir vermögen nichts gegen die Wahrheit, sondern nur für die Wahrheit*.", footnotes: ["℘ Kap. 4,2"] },
      { number: 9, text: "Denn wir freuen uns, wenn wir schwach sind, ihr aber mächtig seid*; um dieses beten wir auch, um eure Vervollkommnung.", footnotes: ["℘ 1Kor 4,10"] },
      { number: 10, text: "Deswegen schreibe ich dieses abwesend, damit ich anwesend nicht Strenge anwenden muss* nach der Vollmacht, die der Herr mir gegeben hat zur Erbauung* und nicht zur Zerstörung.", footnotes: ["℘ V. 2; 1Kor 4,21", "o. zum Aufbau"] },
      { number: 11, text: "Im Übrigen, Brüder, freut euch*, lasst euch zurechtbringen*, lasst euch ermuntern, seid eines Sinnes*, haltet Frieden*! Und der Gott der Liebe und des Friedens* wird mit euch sein*.", heading: "Schlussermahnungen, Grüße, Segenswunsch", footnotes: ["℘ Phil 4,4", "o. vollkommen machen", "℘ 1Kor 1,10", "℘ Mk 9,50", "℘ Röm 15,33", "℘ Phil 4,9"] },
      { number: 12, text: "Grüßt einander mit heiligem Kuss*! Es grüßen euch alle Heiligen*.", footnotes: ["℘ Röm 16,16", "℘ 1Kor 16,20"] },
      { number: 13, text: "Die Gnade des Herrn Jesus Christus* und die Liebe Gottes* und die Gemeinschaft des Heiligen Geistes sei mit euch allen!", footnotes: ["℘ Röm 16,20", "℘ Jud 21"] },
    ]},
  ]
};
